import urllib.request, urllib.parse, json
base='https://geo.salvador.ba.gov.br/imageserver/rest/services'
def get(url):
 req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
 with urllib.request.urlopen(req,timeout=30) as r:return json.load(r)
root=get(base+'?f=pjson')
print('ROOT_FOLDERS',root.get('folders'))
print('ROOT_SERVICES',len(root.get('services',[])))
keys=('mdt','mds','mde','terrain','terreno','elev','lidar','curva','orto','maquete')
def dump(prefix,data):
 for s in data.get('services',[]):
  name=s.get('name',''); typ=s.get('type','')
  if any(k in name.lower() for k in keys): print('MATCH',prefix,name,typ)
 for s in data.get('services',[]): print('SERVICE',prefix,s.get('name'),s.get('type'))
dump('',root)
for folder in root.get('folders',[]):
 try:
  data=get(base+'/'+urllib.parse.quote(folder,safe='')+'?f=pjson')
  print('FOLDER',folder,'SERVICES',len(data.get('services',[])))
  dump(folder,data)
 except Exception as e: print('FOLDER_ERROR',folder,repr(e))
